import itertools

def check_harmonious(matrix):
    R = len(matrix)
    if R == 0:
        return False

    # Check row sets X_i
    row_sets = set()
    for i in range(R):
        row_set = frozenset(matrix[i])
        if row_set in row_sets:
            return False # Not distinct
        row_sets.add(row_set)

    # Check column sets Y_j
    col_sets = set()
    for j in range(R):
        col_list = [matrix[i][j] for i in range(R)]
        col_set = frozenset(col_list)
        if col_set in col_sets:
            return False # Not distinct
        col_sets.add(col_set)

    return True

def solve_r3_n4():
    R = 3
    n = 4

    # Iterate over all possible assignments of 3x3 matrix entries from {1, 2, 3, 4}
    possible_entries = range(1, n + 1)

    for matrix_tuple in itertools.product(possible_entries, repeat=R*R):
        matrix = [list(matrix_tuple[i*R : (i+1)*R]) for i in range(R)]
        if check_harmonious(matrix):
            print("Found solution for R=3, n=4:")
            for row in matrix:
                print(row)
            return True

    print("No solution found for R=3, n=4.")
    return False

